// French A2 practice rooms: 6 modules x 12 rooms x 3 questions.
window.frRooms = window.frRooms || {};
window.frRooms.A2 = [
  // Module 1: Talking About the Past (Passé composé)
  [
    {t:"Past-time words",s:"Vocabulary",qs:[{q:"What does 'hier' mean?",opts:["tomorrow","today","last week","yesterday"],a:3,ex:"'Hier' points to the day before today, so it usually goes with a past tense like the passé composé."}, {q:"How do you say 'last weekend' in French?",opts:["le week-end prochain","ce week-end-ci","le week-end dernier","le dernier jour"],a:2,ex:"'Dernier' after a time noun means 'last/previous'; 'prochain' would mean 'next'."}, {q:"'J'ai mangé' means…",opts:["I eat","I ate","I will eat","I am eating"],a:1,ex:"Avoir in the present + past participle (mangé) forms the passé composé, a completed past action."}]},
    {t:"Weekend story words",s:"Vocabulary",qs:[{q:"'Après ça' means…",opts:["after that","before that","during that","because of that"],a:0,ex:"'Après' means 'after', so 'après ça' moves a story on to the next event."}, {q:"Which phrase means 'she left'?",opts:["elle part","elle est arrivée","elle a pris","elle est partie"],a:3,ex:"Partir takes être, and the participle gets -e because the subject 'elle' is feminine."}, {q:"Odd one out: which is NOT a past-time expression?",opts:["hier","avant-hier","demain","la semaine dernière"],a:2,ex:"'Demain' means 'tomorrow'; the others all refer to the past."}]},
    {t:"Sounds of the past participle",s:"Pronunciation",qs:[{q:"Listen. How is the final -é of 'mangé' pronounced?",opts:["it is silent","like the e in 'café'","like the e in 'le'","like the i in 'ski'"],a:1,ex:"The accent aigu gives a closed [e] sound, the same as in 'café'.",say:"J'ai mangé."}, {q:"Listen. Which pair sounds exactly the same in spoken French?",opts:["mangé / manger","mange / mangé","fini / finir","vu / vous"],a:0,ex:"The -é and -er endings are both said [e], so you must think about the spelling when you write.",say:"mangé, manger"}, {q:"Listen. What sound links 'sommes' and 'allés'?",opts:["an s sound","a t sound","no sound, there is a pause","a z sound"],a:3,ex:"In liaison a final s is pronounced [z] before a vowel: sommes‿allés.",say:"Nous sommes allés à Paris."}]},
    {t:"Avoir + past participle",s:"Grammar",qs:[{q:"Complete: 'Hier, j'___ regardé un film.'",opts:["suis","as","ai","est"],a:2,ex:"Regarder takes avoir, and the je form of avoir is 'ai' (shortened to j'ai)."}, {q:"What is the past participle of 'finir'?",opts:["finé","fini","finu","finit"],a:1,ex:"Regular -ir verbs drop the -r: finir becomes fini."}, {q:"Complete: 'Nous ___ vendu la voiture.'",opts:["avons","sommes","avez","ont"],a:0,ex:"Vendre takes avoir, and 'nous' needs the form 'avons'; -re verbs make participles in -u."}]},
    {t:"Être verbs and agreement",s:"Grammar",qs:[{q:"Complete: 'Marie est ___ au cinéma.'",opts:["allé","allés","aller","allée"],a:3,ex:"With être the participle agrees with the subject: Marie is feminine singular, so add -e."}, {q:"Which sentence about the guests is correct?",opts:["Ils ont arrivés à midi.","Ils sont arrivé à midi.","Ils sont arrivés à midi.","Ils ont arrivé à midi."],a:2,ex:"Arriver is a movement verb that takes être, and the participle agrees with 'ils' (+s)."}, {q:"Which verb takes être in the passé composé?",opts:["manger","venir","prendre","voir"],a:1,ex:"Venir is one of the DR MRS VANDERTRAMP verbs of movement; the others take avoir."}]},
    {t:"Reading: Léa's weekend",s:"Reading",qs:[{q:"Read: 'Samedi, Léa est allée au marché. Elle a acheté des fruits. Le soir, elle a regardé un film avec Paul.' What did Léa buy?",opts:["fruit","a film","bread","flowers"],a:0,ex:"'Elle a acheté des fruits' means she bought fruit; the film was something she watched."}, {q:"Read: 'Dimanche, Tom est resté à la maison parce qu'il était fatigué. Il a lu un livre.' Why did Tom stay at home?",opts:["It was raining.","He was ill.","He had to work.","He was tired."],a:3,ex:"'Parce qu'il était fatigué' gives the reason: fatigué means tired."}, {q:"Read the message: 'Salut ! Hier soir, nous sommes sortis au restaurant, puis nous avons dansé.' What happened after the restaurant?",opts:["They went home.","They watched TV.","They danced.","They ate dessert."],a:2,ex:"'Puis' means 'then', so 'nous avons dansé' happened after the restaurant."}]},
    {t:"Listening: what did they do?",s:"Listening",qs:[{q:"Listen. Where did the speaker go?",opts:["to the mountains","to the beach","to the cinema","to the market"],a:1,ex:"'Je suis allé à la plage' – la plage is the beach.",say:"Le week-end dernier, je suis allé à la plage."}, {q:"Listen. How did she travel?",opts:["by train","by car","by bus","by plane"],a:0,ex:"'Elle a pris le train' – prendre le train means to take the train.",say:"Hier, elle a pris le train pour Lyon."}, {q:"Listen. When did they come home?",opts:["at seven","at twelve","at ten","at eleven"],a:3,ex:"'Onze heures' is eleven o'clock; rentrer (to come home) takes être.",say:"Nous sommes rentrés à onze heures."}]},
    {t:"Talking about your weekend",s:"Speaking",qs:[{q:"A friend asks: 'Qu'est-ce que tu as fait ce week-end ?' Best reply?",opts:["Je joue au foot avec des amis.","Je vais jouer au foot demain.","J'ai joué au foot avec des amis.","Oui, j'aime beaucoup le foot."],a:2,ex:"The question is in the passé composé, so you answer with a completed past action."}, {q:"Someone asks 'Tu es sorti hier soir ?' You stayed in. What do you say?",opts:["Non, je reste à la maison.","Non, je suis resté à la maison.","Non, j'ai resté à la maison.","Non, je suis restant à la maison."],a:1,ex:"Rester takes être in the passé composé: je suis resté(e)."}, {q:"Your friend says 'Je suis allé à Rome !' Which follow-up question is correct?",opts:["Tu as visité le Colisée ?","Tu visites le Colisée ?","Tu es visité le Colisée ?","Tu as visiter le Colisée ?"],a:0,ex:"Visiter takes avoir and needs its participle visité to talk about the finished trip."}]},
    {t:"Writing a diary entry",s:"Writing",qs:[{q:"Choose the correctly written sentence about the girls.",opts:["Elles ont parties tôt.","Elles sont parti tôt.","Elles sont partis tôt.","Elles sont parties tôt."],a:3,ex:"Partir takes être; with 'elles' (feminine plural) the participle ends in -es."}, {q:"Fill the gap: 'Hier, j'ai ___ une lettre à ma grand-mère.'",opts:["écrivé","écri","écrit","écrire"],a:2,ex:"Écrire has an irregular participle: écrit."}, {q:"Which is the correct word order for 'I didn't see the film'?",opts:["Je n'ai vu pas le film.","Je n'ai pas vu le film.","Je ne pas ai vu le film.","Je n'ai le film pas vu."],a:1,ex:"In the passé composé, ne…pas goes around the auxiliary: n'ai pas + participle."}]},
    {t:"Weekends in France",s:"Culture",qs:[{q:"In France, many shops are closed on which day?",opts:["Sunday","Saturday","Friday","Wednesday"],a:0,ex:"Sunday is traditionally a rest day in France, so many shops close or open only in the morning."}, {q:"A French friend says 'J'ai fait la grasse matinée.' What did they do?",opts:["They had a big breakfast.","They went jogging.","They worked late.","They slept in."],a:3,ex:"'Faire la grasse matinée' is an idiom for staying in bed late in the morning."}, {q:"On Monday, which question do French colleagues ask about your weekend?",opts:["Tu passes un bon week-end ?","Tu vas passer un bon week-end ?","Tu as passé un bon week-end ?","Tu passeras un bon week-end ?"],a:2,ex:"On Monday the weekend is finished, so you ask about it in the passé composé."}]},
    {t:"Review: the passé composé",s:"Review",qs:[{q:"What is the past participle of 'prendre'?",opts:["prendu","pris","prené","prit"],a:1,ex:"Prendre is irregular: j'ai pris (and also appris, compris)."}, {q:"Which verb is NOT conjugated with être?",opts:["marcher","tomber","naître","arriver"],a:0,ex:"Marcher (to walk) takes avoir; tomber, naître and arriver are DR MRS VANDERTRAMP verbs."}, {q:"Translate: 'She left after that.'",opts:["Elle est partie avant ça.","Elle part après ça.","Elle a parti après ça.","Elle est partie après ça."],a:3,ex:"Partir uses être with feminine agreement, and 'après ça' means 'after that'."}]},
    {t:"Challenge: tricky past forms",s:"Challenge",qs:[{q:"Complete: 'Les filles sont ___ à la maison à minuit.'",opts:["rentrés","rentré","rentrées","rentrée"],a:2,ex:"Les filles is feminine plural, so the être participle takes -es."}, {q:"Which sentence about the rubbish bin is correct?",opts:["Je suis sorti la poubelle.","J'ai sorti la poubelle.","J'ai sortie la poubelle.","Je suis sortie la poubelle."],a:1,ex:"When sortir has a direct object (la poubelle) it takes avoir, and there's no agreement with the subject."}, {q:"Which is the passé composé of 'il naît'?",opts:["il est né","il a né","il est naît","il a naquit"],a:0,ex:"Naître takes être and has the irregular participle né."}]}
  ],
  // Module 2: Getting Around & Asking Directions
  [
    {t:"Direction words",s:"Vocabulary",qs:[{q:"'Tout droit' means…",opts:["turn right","all the way back","right here","straight ahead"],a:3,ex:"'Tout droit' means continue straight on; 'à droite' would be 'on the right'."}, {q:"How do you say 'on the left'?",opts:["à droite","en face","à gauche","au fond"],a:2,ex:"Gauche is left; à droite is right."}, {q:"What is 'le carrefour'?",opts:["the bridge","the crossroads","the square","the traffic lights"],a:1,ex:"Un carrefour is where several streets meet; the square is 'la place'."}]},
    {t:"Places and shopping",s:"Vocabulary",qs:[{q:"'En face de' means…",opts:["opposite","next to","behind","far from"],a:0,ex:"'En face de' means facing, on the other side; 'à côté de' means next to."}, {q:"What are 'les soldes'?",opts:["the coins","the receipts","the shop windows","the sales"],a:3,ex:"Les soldes are the reduced-price sales periods in shops."}, {q:"What is the opposite of 'près de'?",opts:["à côté de","en face de","loin de","entre"],a:2,ex:"Près de means near, so its opposite is loin de (far from)."}]},
    {t:"Sounds: droite, gauche",s:"Pronunciation",qs:[{q:"Listen. Which word did you hear?",opts:["droit","droite","drôle","doigt"],a:1,ex:"In 'droite' you hear the final t because of the -e; in 'droit' the t is silent.",say:"à droite"}, {q:"Listen. How is the 'au' in 'gauche' pronounced?",opts:["like the o in 'go'","like the ow in 'cow'","like the a in 'cat'","like the u in 'cut'"],a:0,ex:"The spelling 'au' always makes a closed [o] sound in French.",say:"à gauche"}, {q:"Listen. Which syllable of 'carrefour' is stressed?",opts:["the first: car-","the middle: -re-","the first and the last","the last: -four"],a:3,ex:"French puts a light stress on the last pronounced syllable of a word or group.",say:"le carrefour"}]},
    {t:"à + le = au",s:"Grammar",qs:[{q:"Complete: 'Comment aller ___ marché ?'",opts:["à le","à la","au","aux"],a:2,ex:"Marché is masculine, and à + le always contracts to au."}, {q:"Complete: 'La pharmacie est à côté ___ la banque.'",opts:["à","de","du","des"],a:1,ex:"The expression is 'à côté de'; before la it stays 'de la'."}, {q:"Complete: 'Le café est en face ___ hôtel.'",opts:["de l'","du","de le","à l'"],a:0,ex:"Before a vowel or silent h, de + le becomes de l', not du."}]},
    {t:"Prepositions in context",s:"Grammar",qs:[{q:"Complete: 'Le parc est à côté ___ musée.'",opts:["de le","au","de la","du"],a:3,ex:"Musée is masculine, and de + le contracts to du."}, {q:"Which instruction for the second street is correct?",opts:["Prenez la deux rue à droite.","Prenez le deuxième rue à droite.","Prenez la deuxième rue à droite.","Prenez la deuxième rue au droite."],a:2,ex:"Ordinals add -ième, rue is feminine (la), and the phrase is always 'à droite'."}, {q:"Complete: 'La boulangerie est ___ la poste et le cinéma.'",opts:["à côté","entre","en face","près"],a:1,ex:"'Entre … et …' means between two places; the other options would need 'de'."}]},
    {t:"Reading: a directions note",s:"Reading",qs:[{q:"Read: 'Sortez du métro, allez tout droit, puis prenez la première rue à gauche. Mon immeuble est en face de la boulangerie.' Where is the building?",opts:["opposite the bakery","next to the bakery","behind the métro","in the first street right"],a:0,ex:"'En face de la boulangerie' means opposite the bakery."}, {q:"Read the sign: 'Soldes : -30 % sur toutes les chaussures !' What does it mean?",opts:["Shoes cost 30 euros.","Only 30 pairs are left.","Shoes are 30% dearer.","All shoes are 30% off."],a:3,ex:"'Soldes' are sales and '-30 %' shows the price reduction on all shoes."}, {q:"Read: 'Pardon, la gare est loin ? — Non, c'est à cinq minutes à pied.' How far is the station?",opts:["five minutes by bus","five kilometres","five minutes on foot","fifteen minutes on foot"],a:2,ex:"'À pied' means on foot, and 'cinq minutes' is five minutes."}]},
    {t:"Listening: finding the way",s:"Listening",qs:[{q:"Listen. Where should you turn right?",opts:["at the bridge","at the crossroads","at the station","at the traffic lights"],a:1,ex:"'Au carrefour' means at the crossroads.",say:"Tournez à droite au carrefour."}, {q:"Listen. Where is the bank?",opts:["opposite the pharmacy","next to the pharmacy","behind the pharmacy","inside the pharmacy"],a:0,ex:"'En face de' means opposite.",say:"La banque est en face de la pharmacie."}, {q:"Listen. How much is the jacket?",opts:["55 euros","40 euros","65 euros","45 euros"],a:3,ex:"'Quarante-cinq' is 45; cinquante would be 50.",say:"Cette veste coûte quarante-cinq euros."}]},
    {t:"Asking the way, buying clothes",s:"Speaking",qs:[{q:"You want to ask a stranger the way to the station. What do you say?",opts:["Pardon, la gare va bien ?","Pardon, vous êtes à la gare ?","Pardon, pour aller à la gare ?","Pardon, je suis la gare ?"],a:2,ex:"'Pour aller à …?' is the standard short way to ask for directions."}, {q:"In a shop you want the same T-shirt in size M. What do you say?",opts:["Vous l'avez à taille M ?","Vous l'avez en taille M ?","Vous êtes en taille M ?","Vous l'avez pour taille M ?"],a:1,ex:"Sizes use 'en': en taille M, en 38; l' refers back to the T-shirt."}, {q:"The shop assistant asks 'Je peux vous aider ?' You are just looking. Reply?",opts:["Non merci, je regarde seulement.","Non merci, je cherche la gare.","Oui, je regarde beaucoup.","Non merci, je regarde demain."],a:0,ex:"'Je regarde seulement' (I'm just looking) politely tells staff you don't need help yet."}]},
    {t:"Writing directions",s:"Writing",qs:[{q:"Choose the correctly written sentence about the cinema.",opts:["Le cinéma est près la gare.","Le cinéma est près à la gare.","Le cinéma est près du la gare.","Le cinéma est près de la gare."],a:3,ex:"'Près' always needs 'de': près de la gare."}, {q:"Fill the gap in the message: 'Prends la ___ rue à gauche, c'est le numéro 8.'",opts:["trois","troisièmes","troisième","tiers"],a:2,ex:"To say which street in order you need an ordinal: trois becomes troisième."}, {q:"Which question is correctly written?",opts:["Comment aller au la gare ?","Comment aller à la gare ?","Comment à la gare aller ?","Comment aller à le gare ?"],a:1,ex:"Gare is feminine, so 'à la gare'; the infinitive aller comes right after comment."}]},
    {t:"Shopping culture in France",s:"Culture",qs:[{q:"When do the big seasonal sales (les soldes) happen in France?",opts:["twice a year, on official dates","every single weekend","only in December","on any day a shop chooses"],a:0,ex:"French sales periods are regulated: one in winter and one in summer, on dates set by the state."}, {q:"When entering a small shop in France, what is polite?",opts:["Say nothing until you pay.","Wave without speaking.","Say 'Salut' to everyone.","Say 'Bonjour' to the staff."],a:3,ex:"Greeting shop staff with 'Bonjour' is expected; 'Salut' is too informal for strangers."}, {q:"In French towns, what does a lit green cross sign usually show?",opts:["a hospital","a bank","a pharmacy","a church"],a:2,ex:"The green cross is the symbol of French pharmacies."}]},
    {t:"Review: getting around",s:"Review",qs:[{q:"'À côté de' means…",opts:["opposite","next to","between","behind"],a:1,ex:"'À côté de' means beside or next to; 'en face de' means opposite."}, {q:"Complete: 'Vous allez ___ gare ?'",opts:["à la","au","aux","à le"],a:0,ex:"Gare is feminine singular, so à + la stays 'à la'."}, {q:"A local says 'C'est au bout de la rue.' Where is it?",opts:["at the start of the street","across the street","in the next street","at the end of the street"],a:3,ex:"'Au bout de' means at the end of."}]},
    {t:"Challenge: directions and shops",s:"Challenge",qs:[{q:"Complete: 'Le restaurant est en face ___ Galeries Lafayette.'",opts:["de les","aux","des","de"],a:2,ex:"Galeries is plural, and de + les always contracts to des."}, {q:"Which directions are correct?",opts:["Traversez la place, puis c'est le deuxième rue à droite.","Traversez la place, puis c'est la deuxième rue à droite.","Traversez la place, puis c'est la deuxième rue au droite.","Traversez à la place, puis c'est la deux rue à droite."],a:1,ex:"Traverser takes a direct object, rue is feminine, ordinals end in -ième, and you say 'à droite'."}, {q:"In a shop the assistant says 'Elle vous va très bien !' What does she mean?",opts:["It suits you very well.","It is going very well.","She is coming to you.","It is very cheap."],a:0,ex:"'Aller à quelqu'un' means to suit someone; elle refers to a feminine item like la robe."}]}
  ],
  // Module 3: Reflexive & Modal Expressions
  [
    {t:"Daily routine words",s:"Vocabulary",qs:[{q:"'Se réveiller' means…",opts:["to get up","to fall asleep","to get dressed","to wake up"],a:3,ex:"Se réveiller is waking up; getting out of bed is se lever."}, {q:"Which verb means 'to get dressed'?",opts:["se laver","se coucher","s'habiller","se brosser"],a:2,ex:"S'habiller comes from 'les habits' (clothes)."}, {q:"'Le rendez-vous' means…",opts:["the meeting room","the appointment","the receipt","the waiting room"],a:1,ex:"Un rendez-vous is a fixed meeting time, e.g. with a doctor."}]},
    {t:"Can, want, must",s:"Vocabulary",qs:[{q:"'Devoir' means…",opts:["must / to have to","can / to be able to","to want","to know how"],a:0,ex:"Devoir expresses obligation; pouvoir is 'can' and vouloir is 'want'."}, {q:"Which verb is the opposite of 'se lever' in your routine?",opts:["se réveiller","s'habiller","se doucher","se coucher"],a:3,ex:"Se lever is getting up, se coucher is going to bed."}, {q:"'Mardi, ça vous va ?' means…",opts:["Are you going on Tuesday?","Did you go on Tuesday?","Does Tuesday suit you?","How was Tuesday?"],a:2,ex:"'Ça vous va ?' asks if something suits you, a key phrase for making appointments."}]},
    {t:"Sounds: s'habiller, vous vous",s:"Pronunciation",qs:[{q:"Listen. How is the 'ille' in 's'habille' pronounced?",opts:["like the l in 'ill'","like the y in 'yes'","like the ee in 'see'","it is silent"],a:1,ex:"After a vowel, -ille is usually said [j], like the y in 'yes'.",say:"Il s'habille."}, {q:"Listen. Which 'vous' is linked to the next word with a z sound?",opts:["the second, before 'habillez'","the first, before 'vous'","both of them","neither of them"],a:0,ex:"Liaison happens only before a vowel sound, so only the second vous links to habillez.",say:"Vous vous habillez."}, {q:"Listen. Which modal verb form did you hear?",opts:["peur","pour","pu","peux"],a:3,ex:"'Peux' has the [ø] vowel and the x is silent; peur ends with a clear r.",say:"Je peux venir."}]},
    {t:"Reflexive pronouns",s:"Grammar",qs:[{q:"Complete: 'Tu ___ lèves à quelle heure ?'",opts:["se","me","te","toi"],a:2,ex:"Each subject has its own reflexive pronoun: tu goes with te."}, {q:"Complete: 'Nous ___ couchons tard.'",opts:["se","nous","vous","nos"],a:1,ex:"With nous the reflexive pronoun is also nous: nous nous couchons."}, {q:"Complete: 'Je veux ___ un café.'",opts:["prendre","prends","pris","prenez"],a:0,ex:"After a modal like vouloir, the second verb stays in the infinitive."}]},
    {t:"Reflexives in the past, modals",s:"Grammar",qs:[{q:"Complete: 'Elle s'est ___ à six heures.'",opts:["levé","lever","levés","levée"],a:3,ex:"Reflexive verbs take être in the passé composé, so the participle agrees with 'elle'."}, {q:"Which sentence about waking up is correct?",opts:["Je m'ai réveillé tard.","Je suis me réveillé tard.","Je me suis réveillé tard.","Je me suis réveiller tard."],a:2,ex:"Reflexives use être, and the pronoun goes before the auxiliary: je me suis …"}, {q:"Complete: 'Ils ne ___ pas venir ce soir.'",opts:["peut","peuvent","pouvez","pouvoir"],a:1,ex:"Pouvoir is irregular; the ils form is peuvent, followed by an infinitive."}]},
    {t:"Reading: routines and rules",s:"Reading",qs:[{q:"Read: 'Le matin, Julie se réveille à 7 h, elle se douche et elle s'habille. Elle doit partir à 8 h.' What must Julie do at 8?",opts:["leave","wake up","shower","get dressed"],a:0,ex:"'Elle doit partir' – devoir + infinitive shows what she has to do: leave."}, {q:"Read: 'Cabinet du Dr Martin : rendez-vous possible jeudi à 15 h ou vendredi à 10 h.' When can you see the doctor on Friday?",opts:["at 3 p.m.","at 5 p.m.","at noon","at 10 a.m."],a:3,ex:"Vendredi is Friday, and 10 h means 10 a.m. in the 24-hour clock."}, {q:"Read the sign: 'Il est interdit de fumer. Vous ne pouvez pas utiliser votre portable.' What can't you do?",opts:["enter the room","sit down","use your mobile phone","talk quietly"],a:2,ex:"'Vous ne pouvez pas utiliser votre portable' means you can't use your mobile."}]},
    {t:"Listening: routines",s:"Listening",qs:[{q:"Listen. What does the person do at eleven?",opts:["gets up","goes to bed","has a shower","has dinner"],a:1,ex:"'Je me couche' means I go to bed.",say:"Je me couche à onze heures."}, {q:"Listen. When can the person come?",opts:["Tuesday at nine","Thursday at nine","Tuesday at noon","Monday at nine"],a:0,ex:"Mardi is Tuesday and neuf heures is nine o'clock.",say:"Je peux venir mardi à neuf heures."}, {q:"Listen. What is necessary?",opts:["taking the train at 3","waiting three minutes","buying three tickets","taking bus number 3"],a:3,ex:"'Il faut' + infinitive means it is necessary: take bus number three.",say:"Il faut prendre le bus numéro trois."}]},
    {t:"Making an appointment",s:"Speaking",qs:[{q:"The receptionist asks 'Mardi à 10 h, ça vous va ?' You agree. Say:",opts:["Oui, je vais très bien.","Oui, ça va me voir.","Oui, ça me va très bien.","Oui, vous allez bien."],a:2,ex:"You answer 'ça vous va' with 'ça me va' – it suits me."}, {q:"You want to ask if you can come later. Say:",opts:["Est-ce que je veux venir plus tard ?","Est-ce que je peux venir plus tard ?","Est-ce que je viens plus tôt ?","Est-ce que je suis venu plus tard ?"],a:1,ex:"Pouvoir + infinitive asks for permission or possibility."}, {q:"You can't make the appointment. What do you say?",opts:["Désolé, je ne peux pas venir.","Désolé, je ne veux venir pas.","Désolé, je ne dois pas venu.","Désolé, je peux ne venir pas."],a:0,ex:"Ne…pas goes around the modal, and the infinitive follows: je ne peux pas venir."}]},
    {t:"Writing your routine",s:"Writing",qs:[{q:"Choose the correctly written sentence about the walk.",opts:["Nous nous avons promenés au parc.","Nous sommes nous promenés au parc.","Nous nous sommes promener au parc.","Nous nous sommes promenés au parc."],a:3,ex:"Se promener is reflexive: être, pronoun before the auxiliary, and agreement with nous."}, {q:"Fill the gap: 'Désolée, je dois ___ mon rendez-vous de lundi.'",opts:["annulé","annule","annuler","annulais"],a:2,ex:"After devoir the next verb is an infinitive: annuler (to cancel)."}, {q:"Which is the correct word order for 'I must not be late'?",opts:["Je dois ne pas en retard être.","Je ne dois pas être en retard.","Je ne pas dois être en retard.","Je dois pas ne être en retard."],a:1,ex:"Ne…pas surrounds the conjugated modal, then the infinitive être follows."}]},
    {t:"Politeness and register",s:"Culture",qs:[{q:"How do French people usually write an appointment at 3:30 pm?",opts:["15 h 30","3:30 pm","3 h 30 PM","15.30 pm"],a:0,ex:"France uses the 24-hour clock with 'h' for heures in schedules and appointments."}, {q:"Which is the most polite way to ask a stranger for help?",opts:["Tu peux m'aider, s'il te plaît, toi ?","Aide-moi tout de suite, s'il te plaît !","Vous devez m'aider, c'est obligatoire.","Pourriez-vous m'aider, s'il vous plaît ?"],a:3,ex:"Strangers get 'vous', and the conditional 'pourriez-vous' softens the request."}, {q:"A French colleague says 'On se tutoie ?' What are they suggesting?",opts:["meeting each other later","calling each other tonight","using 'tu' with each other","sitting next to each other"],a:2,ex:"Se tutoyer is a reciprocal verb: to say 'tu' to each other instead of 'vous'."}]},
    {t:"Review: reflexives and modals",s:"Review",qs:[{q:"Which is the passé composé of 'tu t'habilles' (said to a boy)?",opts:["tu t'as habillé","tu t'es habillé","tu es t'habillé","tu t'es habiller"],a:1,ex:"Reflexives take être; for tu that is 'es', and the pronoun t' comes before it."}, {q:"'Il faut partir' means…",opts:["We have to leave.","He wants to leave.","He is leaving.","We can leave."],a:0,ex:"'Il faut' is impersonal and expresses necessity, so it means 'we/one must'."}, {q:"Complete: 'Vous ___ rester ici ce soir ?' (want)",opts:["veulent","voulons","vouloir","voulez"],a:3,ex:"Vouloir with vous is voulez, followed by the infinitive rester."}]},
    {t:"Challenge: past reflexives",s:"Challenge",qs:[{q:"Which sentence about washing hands is correct?",opts:["Elles se sont lavées les mains.","Elles s'ont lavé les mains.","Elles se sont lavé les mains.","Elles se sont laver les mains."],a:2,ex:"When a direct object (les mains) follows, the participle of a reflexive does not agree."}, {q:"Complete: 'Hier, nous ___ dû partir tôt.'",opts:["sommes","avons","nous sommes","étions"],a:1,ex:"Devoir is not reflexive or a movement verb, so its passé composé uses avoir: nous avons dû."}, {q:"Choose the negative of 'Il s'est rasé.'",opts:["Il ne s'est pas rasé.","Il ne s'est rasé pas.","Il s'est ne pas rasé.","Il ne pas s'est rasé."],a:0,ex:"Ne goes before the reflexive pronoun and pas after the auxiliary."}]}
  ],
  // Module 4: Stories, Weather & Context
  [
    {t:"Weather words",s:"Vocabulary",qs:[{q:"'Il pleut' means…",opts:["It's snowing.","It's windy.","It's cloudy.","It's raining."],a:3,ex:"Il pleut comes from pleuvoir, to rain; snowing is il neige."}, {q:"How do you say 'It's cold' about the weather?",opts:["Il est froid.","Il a froid.","Il fait froid.","C'est fait froid."],a:2,ex:"Weather uses 'il fait'; 'il a froid' means a person feels cold."}, {q:"Which season is 'le printemps'?",opts:["summer","spring","autumn","winter"],a:1,ex:"Le printemps is spring; summer is l'été, autumn l'automne, winter l'hiver."}]},
    {t:"Story words",s:"Vocabulary",qs:[{q:"'Soudain' means…",opts:["suddenly","slowly","sometimes","soon"],a:0,ex:"Soudain introduces an unexpected event, usually in the passé composé."}, {q:"'Il était une fois' is used to…",opts:["end a letter","describe the weather","order food","begin a fairy tale"],a:3,ex:"'Il était une fois' is the classic opening of a tale, like 'Once upon a time'."}, {q:"'Pendant que' means…",opts:["before","after","while","until"],a:2,ex:"Pendant que links two actions happening at the same time."}]},
    {t:"Sounds: pleut, jouais, automne",s:"Pronunciation",qs:[{q:"Listen. Which vowel sound is in 'pleut'?",opts:["the 'ou' sound, as in 'vous'","the 'eu' sound, as in 'deux'","the 'u' sound, as in 'tu'","the 'é' sound, as in 'été'"],a:1,ex:"The letters 'eu' make a rounded [ø] sound, as in deux and peu.",say:"Il pleut."}, {q:"Listen. How does the imparfait ending '-ais' sound?",opts:["like the è in 'mère'","like 'ice' in English","like the a in 'chat'","like the i in 'lit'"],a:0,ex:"-ais, -ait and -aient all sound like an open è; the final letters are silent.",say:"Je jouais."}, {q:"Listen. Is the m in 'automne' pronounced?",opts:["Yes, like 'autom-ne'.","Yes, but the n is silent.","Only in the plural.","No, it is silent."],a:3,ex:"Automne is said 'o-tonne': the m is a silent letter.",say:"l'automne"}]},
    {t:"The imparfait",s:"Grammar",qs:[{q:"Complete (imparfait): 'Quand j'étais petit, je ___ au foot.'",opts:["ai joué","joue","jouais","jouerai"],a:2,ex:"Childhood habits are described with the imparfait: je jouais."}, {q:"What is the imparfait stem of 'faire'?",opts:["fai-","fais-","fer-","fis-"],a:1,ex:"The stem comes from the nous form (nous faisons) minus -ons: fais-."}, {q:"Complete: 'Hier, il ___ beau.'",opts:["faisait","fait","faisais","faisaient"],a:0,ex:"Weather in the past is background description, so imparfait il faisait."}]},
    {t:"Imparfait or passé composé?",s:"Grammar",qs:[{q:"Complete: 'Hier soir, je lisais quand soudain le téléphone ___.'",opts:["sonnait","sonne","sonnera","a sonné"],a:3,ex:"A sudden single event interrupting a background action takes the passé composé."}, {q:"Which sentence describes a habit in the past?",opts:["Dimanche, nous sommes allés chez mamie.","Dimanche, nous allons chez mamie.","Le dimanche, nous allions chez mamie.","Dimanche, nous irons chez mamie."],a:2,ex:"'Le dimanche' means every Sunday, and repeated past habits use the imparfait."}, {q:"Complete: 'Il ___ et il faisait froid quand nous sommes sortis.'",opts:["a neigé","neigeait","neige","neigera"],a:1,ex:"The weather is the background scene, so it goes in the imparfait like 'faisait'."}]},
    {t:"Reading: a short story",s:"Reading",qs:[{q:"Read: 'Ce jour-là, il pleuvait. Marc attendait le bus. Soudain, une voiture s'est arrêtée.' What was the weather like?",opts:["rainy","sunny","snowy","windy"],a:0,ex:"'Il pleuvait' is the imparfait of pleuvoir: it was raining."}, {q:"Read: 'Quand j'étais enfant, j'habitais à la campagne. Tous les étés, je nageais dans la rivière.' What did the writer do every summer?",opts:["went to the city","climbed mountains","went fishing","swam in the river"],a:3,ex:"'Je nageais dans la rivière' – the imparfait shows a repeated summer habit."}, {q:"Read the forecast: 'Demain matin, nuageux. L'après-midi, il y aura du soleil et il fera 22 degrés.' What will the afternoon be like?",opts:["cloudy, 22 degrees","rainy, 12 degrees","sunny, 22 degrees","sunny, 12 degrees"],a:2,ex:"'Il y aura du soleil' means it will be sunny; nuageux applies only to the morning."}]},
    {t:"Listening: weather and stories",s:"Listening",qs:[{q:"Listen. What is the weather doing?",opts:["raining since this morning","snowing since this morning","snowing since yesterday","windy since this morning"],a:1,ex:"'Il neige depuis ce matin' – depuis + present means it started this morning and continues.",say:"Il neige depuis ce matin."}, {q:"Listen. What did they do second?",opts:["went to the cinema","ate","went home","went to a café"],a:0,ex:"'D'abord' marks the first action and 'ensuite' the next one: the cinema.",say:"D'abord on a mangé, ensuite on est allés au cinéma."}, {q:"Listen. What did the speaker have as a child?",opts:["a dog","a bike","a horse","a cat"],a:3,ex:"'J'avais un chat' – avoir in the imparfait describes a past situation.",say:"Quand j'étais petite, j'avais un chat."}]},
    {t:"Chatting about weather",s:"Speaking",qs:[{q:"A friend asks 'Quel temps fait-il chez toi ?' Best reply?",opts:["Il est beau, il a du soleil.","Je fais beau aujourd'hui.","Il fait beau, il y a du soleil.","Il fait beau temps hier."],a:2,ex:"Weather answers use 'il fait' and 'il y a du soleil'."}, {q:"You want to start telling a story about your childhood. Which opening fits?",opts:["Quand j'ai été petit, …","Quand j'étais petit, …","Quand je suis petit, …","Quand je serai petit, …"],a:1,ex:"Childhood is a past background state, so it uses the imparfait j'étais."}, {q:"Your friend says 'Il pleut encore !' Which reply makes sense?",opts:["Oh non, j'ai oublié mon parapluie !","Oui, il fait très chaud et sec !","Super, on va bronzer à la plage !","Oui, il ne pleut jamais ici."],a:0,ex:"Rain means you need un parapluie (an umbrella); the other replies contradict the rain."}]},
    {t:"Writing a story",s:"Writing",qs:[{q:"Choose the correctly written weather description.",opts:["Il faisait froid et il avait du vent.","Il était froid et il y avait du vent.","Il faisait froid et il y était du vent.","Il faisait froid et il y avait du vent."],a:3,ex:"Use 'il faisait' for temperature and 'il y avait du vent' for wind."}, {q:"Fill the gap: 'D'abord, j'ai pris une douche, ___ j'ai pris le petit-déjeuner.'",opts:["d'abord","il était une fois","ensuite","pendant que"],a:2,ex:"Ensuite (then/next) continues a sequence that starts with d'abord."}, {q:"Which sentence correctly says 'Finally, we went home'?",opts:["Enfin, nous avons rentrés.","Enfin, nous sommes rentrés.","Nous enfin sommes rentrés.","Enfin, rentrés nous sommes."],a:1,ex:"Enfin closes a sequence; rentrer takes être and agrees with nous."}]},
    {t:"Weather and stories in France",s:"Culture",qs:[{q:"In France, temperatures in weather forecasts are given in…",opts:["degrees Celsius","degrees Fahrenheit","kelvin","Fahrenheit and Celsius"],a:0,ex:"France uses the metric system, so forecasts give degrees Celsius only."}, {q:"What is 'Le Petit Nicolas'?",opts:["a cartoon about a small dog","a children's song about Paris","a weekly newspaper for kids","funny stories about a schoolboy"],a:3,ex:"Le Petit Nicolas, by Sempé and Goscinny, tells a boy's school and family adventures."}, {q:"In which month do many French people go on their summer holidays?",opts:["June","October","August","March"],a:2,ex:"Août is the classic holiday month in France, when many offices and shops close."}]},
    {t:"Review: weather and tenses",s:"Review",qs:[{q:"'Il fait beau' means…",opts:["He is handsome.","The weather is nice.","He does it well.","It's getting late."],a:1,ex:"'Il fait' + adjective describes the weather; 'il est beau' would describe a man."}, {q:"Which word introduces a sudden event in a story?",opts:["soudain","pendant que","d'habitude","tous les jours"],a:0,ex:"Soudain marks an unexpected action; the others describe duration or habit."}, {q:"Complete: 'L'été dernier, nous ___ en Italie pendant deux semaines.'",opts:["allions","allons","irons","sommes allés"],a:3,ex:"A finished trip with a clear duration is a completed event, so it takes the passé composé."}]},
    {t:"Challenge: telling a story",s:"Challenge",qs:[{q:"Which pair fits? 'Nous ___ la télé quand l'orage ___.'",opts:["avons regardé / commençait","regardons / a commencé","regardions / a commencé","regardions / commençait"],a:2,ex:"The ongoing action (watching TV) is imparfait; the event that interrupts it is passé composé."}, {q:"What is the imparfait of 'être' with 'nous'?",opts:["nous étaient","nous étions","nous sommes été","nous étons"],a:1,ex:"Être has the irregular imparfait stem ét-, plus the ending -ions for nous."}, {q:"Choose the best ending: 'Il était une fois une princesse qui ___ dans un château.'",opts:["habitait","a habité","habite","habitera"],a:0,ex:"Tales set the scene in the imparfait: where the princess lived is background."}]}
  ],
  // Module 5: Emails, Travel & Review
  [
    {t:"Travel words",s:"Vocabulary",qs:[{q:"'Le billet' means…",opts:["the receipt","the platform","the luggage","the ticket"],a:3,ex:"Un billet de train is a train ticket."}, {q:"How do you say 'to book a room'?",opts:["garder une chambre","ranger une chambre","réserver une chambre","louer une salle"],a:2,ex:"Réserver means to book; une chambre is a bedroom in a hotel."}, {q:"'Le train a du retard' means…",opts:["The train is early.","The train is late.","The train is cancelled.","The train is full."],a:1,ex:"'Avoir du retard' means to be delayed; à l'heure would be on time."}]},
    {t:"Email and station phrases",s:"Vocabulary",qs:[{q:"'Cordialement' is used…",opts:["to close a formal email","to greet a friend","to open a letter","to ask a question"],a:0,ex:"Cordialement (kind regards) is the standard neutral-formal email closing."}, {q:"What is 'le quai' at a station?",opts:["the ticket office","the waiting room","the timetable","the platform"],a:3,ex:"Trains leave from le quai; the ticket office is le guichet."}, {q:"You don't want 'un aller simple' – you want to come back too. What do you ask for?",opts:["un retour simple","un billet simple","un aller-retour","un départ"],a:2,ex:"Un aller-retour (there and back) is a return ticket; un aller simple is one-way."}]},
    {t:"Sounds: Monsieur, quai",s:"Pronunciation",qs:[{q:"Listen. How does the end of 'cordialement' sound?",opts:["like English 'meant'","a nasal vowel, the t is silent","like 'ment' with a clear t","like 'mine' in English"],a:1,ex:"The ending -ment is a nasal [ɑ̃] and the final t is not pronounced.",say:"Cordialement"}, {q:"Listen. How is the 'qu' in 'quai' pronounced?",opts:["like k","like kw","like ch","like g"],a:0,ex:"In French 'qu' is almost always a simple [k] sound.",say:"le quai"}, {q:"Listen. How is 'Monsieur' pronounced?",opts:["'mon-syeur', with nasal 'on'","'mon-see-ur', every letter said","'may-syeu', like 'mes'","'muh-syeu', the r is silent"],a:3,ex:"Monsieur has an irregular pronunciation: the 'on' sounds like 'e' and the final r is silent.",say:"Madame, Monsieur"}]},
    {t:"Polite requests",s:"Grammar",qs:[{q:"Complete: '___-vous me dire à quelle heure part le train ?'",opts:["Pourrions","Pourraient","Pourriez","Pouvoir"],a:2,ex:"The conditional 'pourriez-vous' is the polite form for vous; the others don't match the subject."}, {q:"Which is the formal opening of an email to a company?",opts:["Salut,","Madame, Monsieur,","Coucou,","Cher ami,"],a:1,ex:"'Madame, Monsieur,' is used when you don't know who will read a formal letter."}, {q:"Complete: 'Je voudrais un aller simple ___ Lyon.'",opts:["pour","à","en","de"],a:0,ex:"You buy a ticket 'pour' a destination: un billet pour Lyon."}]},
    {t:"Formal and informal emails",s:"Grammar",qs:[{q:"Which closing matches an email that starts 'Chère Sophie,'?",opts:["Je vous prie d'agréer, Paul","Veuillez agréer, Paul","Salutations distinguées, Paul","Bises, Paul"],a:3,ex:"'Chère Sophie' is informal, so it ends with a friendly closing like Bises."}, {q:"Choose the correct sentence for a formal email.",opts:["Je t'écris au sujet de ma réservation.","Je vous écris au sujet du ma réservation.","Je vous écris au sujet de ma réservation.","Je vous écrit au sujet de ma réservation."],a:2,ex:"Formal emails use vous, 'au sujet de' means 'about', and the je form of écrire ends in -s: j'écris."}, {q:"Complete: 'Je vous serais reconnaissant de me ___ une réponse rapide.'",opts:["donnez","donner","donné","donne"],a:1,ex:"'Reconnaissant de' is followed by an infinitive."}]},
    {t:"Reading: an email and an announcement",s:"Reading",qs:[{q:"Read the email: 'Madame, Monsieur, je souhaite réserver une chambre double pour deux nuits, du 3 au 5 mai. Cordialement, Anne Martin.' How many nights?",opts:["two","three","five","one"],a:0,ex:"'Pour deux nuits' – from the 3rd to the 5th of May is two nights."}, {q:"Read: 'Bonjour, le petit-déjeuner est-il compris dans le prix ? Merci, Luc.' What does Luc want to know?",opts:["what time breakfast is","where breakfast is served","if breakfast is good","if breakfast is included"],a:3,ex:"'Compris dans le prix' means included in the price."}, {q:"Read the announcement: 'Le TGV 6203 à destination de Marseille partira du quai 4 avec un retard de 15 minutes.' What is true?",opts:["The train leaves from platform 15.","The train goes to Paris.","The train leaves 15 minutes late.","The train is cancelled."],a:2,ex:"'Avec un retard de 15 minutes' means a 15-minute delay; the platform is 4."}]},
    {t:"Listening: at the station",s:"Listening",qs:[{q:"Listen. What does the traveller want?",opts:["a one-way ticket to Bordeaux","a return ticket to Bordeaux","a return ticket to Toulouse","a hotel room in Bordeaux"],a:1,ex:"'Un aller-retour' is a return ticket.",say:"Un aller-retour pour Bordeaux, s'il vous plaît."}, {q:"Listen. Which platform does the train leave from?",opts:["7","17","2","11"],a:0,ex:"'Quai numéro sept' is platform 7.",say:"Le train pour Nice part du quai numéro sept."}, {q:"Listen. How long is the booking?",opts:["two nights","three weeks","one night","three nights"],a:3,ex:"'Trois nuits' means three nights.",say:"J'ai réservé une chambre pour trois nuits."}]},
    {t:"At the station and hotel",s:"Speaking",qs:[{q:"At the ticket office you want a one-way ticket to Lyon. Say:",opts:["Un aller-retour pour Lyon, s'il vous plaît.","Une chambre simple pour Lyon, s'il vous plaît.","Un aller simple pour Lyon, s'il vous plaît.","Un quai simple pour Lyon, s'il vous plaît."],a:2,ex:"'Un aller simple' is one-way; an aller-retour would include the journey back."}, {q:"Your train is late and you'll miss your connection. What do you ask the staff?",opts:["Je vais prendre ma correspondance, c'est bien ?","Je vais rater ma correspondance, que dois-je faire ?","J'ai raté mon petit-déjeuner, que dois-je faire ?","Je vais réserver ma correspondance, c'est cher ?"],a:1,ex:"'Rater sa correspondance' means to miss your connecting train."}, {q:"At the hotel reception you have a booking. Say:",opts:["J'ai une réservation au nom de Dupont.","J'ai un rendez-vous au nom de Dupont.","Je suis une réservation de Dupont.","J'ai réservé au nom à Dupont."],a:0,ex:"'Au nom de' (in the name of) is how you identify a booking at a hotel."}]},
    {t:"Writing emails",s:"Writing",qs:[{q:"Choose the correctly written formal closing.",opts:["Veuillez agréer, Madame, mes salutation distinguée.","Veuillez agréez, Madame, mes salutations distinguées.","Veuillez agréer, Madame, mes salutations distingués.","Veuillez agréer, Madame, mes salutations distinguées."],a:3,ex:"After veuillez comes the infinitive agréer, and 'salutations distinguées' is feminine plural."}, {q:"Fill the gap: 'Salut Léo, ___ pour ton message ! À bientôt.'",opts:["pardon","cordialement","merci","veuillez"],a:2,ex:"'Merci pour' thanks someone for something; it fits the friendly tone with Salut."}, {q:"Which subject line fits an email to cancel a hotel booking?",opts:["Réservation de mon annulation","Annulation de ma réservation","Annuler à ma réservation","Mon annulation réservée"],a:1,ex:"Subject lines use a noun phrase: annulation (cancellation) de ma réservation."}]},
    {t:"Email etiquette and travel",s:"Culture",qs:[{q:"In a formal email, which greeting do you use if you don't know the reader's name?",opts:["Madame, Monsieur,","Cher Monsieur Madame,","Bonjour à toi,","Salut à tous,"],a:0,ex:"'Madame, Monsieur,' is the standard formal greeting for an unknown reader."}, {q:"What is the TGV?",opts:["a regional bus network","the Paris metro","a budget airline","France's high-speed train"],a:3,ex:"TGV stands for train à grande vitesse, France's high-speed train."}, {q:"When is 'Bises' used at the end of an email?",opts:["with a bank or company","with business partners","with friends and family","when you apologise formally"],a:2,ex:"'Bises' (kisses) is warm and informal, only for people you know well."}]},
    {t:"Review: emails and travel",s:"Review",qs:[{q:"In 'Chère Julie', why is it 'Chère' and not 'Cher'?",opts:["'Chère' is the formal form.","Julie is female, so it is feminine.","'Cher' is only for objects.","'Chère' goes with first names."],a:1,ex:"Cher is an adjective and agrees in gender: cher Paul, chère Julie."}, {q:"'Un aller-retour' means…",opts:["a return ticket","a one-way ticket","a round table","a delay"],a:0,ex:"Aller (to go) + retour (return): a ticket there and back."}, {q:"Complete: 'Pourriez-vous m'envoyer les horaires ___ trains ?'",opts:["de les","du","aux","des"],a:3,ex:"Trains is plural, so de + les contracts to des."}]},
    {t:"Challenge: formal French",s:"Challenge",qs:[{q:"Which formal sentence is correct?",opts:["Je vous prie de bien vouloir m'envoyez une facture.","Je te prie de bien vouloir m'envoyer une facture, Monsieur.","Je vous prie de bien vouloir m'envoyer une facture.","Je vous prie de bien voulez m'envoyer une facture."],a:2,ex:"After 'prier de' and 'vouloir' the verbs stay infinitive, and Monsieur needs vous."}, {q:"Which greeting and closing mix formal and informal badly?",opts:["Madame, Monsieur … Cordialement","Salut Monsieur le Directeur … Bises","Chère Anna … Bises","Bonjour Madame Roy … Cordialement"],a:1,ex:"'Salut' and 'Bises' are informal and clash with a formal title like Monsieur le Directeur."}, {q:"Complete: 'Suite à une grève, votre train ___ supprimé.'",opts:["a été","a eu","est eu","avait"],a:0,ex:"The passive is être + participle; in the passé composé être becomes 'a été'."}]}
  ],
  // Module 6: Comparisons, Health & the Body
  [
    {t:"Body words",s:"Vocabulary",qs:[{q:"'La tête' means…",opts:["the face","the neck","the hair","the head"],a:3,ex:"La tête is the head; the face is le visage."}, {q:"Which word means 'the back' (body part)?",opts:["le ventre","le cou","le dos","le bras"],a:2,ex:"Le dos is the back; j'ai mal au dos means my back hurts."}, {q:"'Une ordonnance' is…",opts:["an order of food","a prescription","an appointment","an ambulance"],a:1,ex:"The doctor writes une ordonnance, which you take to the pharmacy."}]},
    {t:"More body and comparison words",s:"Vocabulary",qs:[{q:"'Le ventre' means…",opts:["the stomach","the knee","the shoulder","the foot"],a:0,ex:"Le ventre is the stomach or belly; the knee is le genou."}, {q:"What is the opposite of 'plus' in comparisons?",opts:["aussi","mieux","très","moins"],a:3,ex:"Plus means more and moins means less; aussi means as."}, {q:"Which of these is a body part?",opts:["le genre","le jeudi","le genou","le génie"],a:2,ex:"Le genou is the knee; the others mean type, Thursday and genius."}]},
    {t:"Sounds: yeux, dos, meilleur",s:"Pronunciation",qs:[{q:"Listen. How does 'les yeux' sound?",opts:["'lay-yeu', with no liaison","'lay-zyeu', with a z liaison","'less-yeu', with an s","'lay-yucks', with an x"],a:1,ex:"The s of les links to the vowel of yeux as [z], and the x of yeux is silent.",say:"les yeux"}, {q:"Listen. Is the s at the end of 'dos' pronounced?",opts:["No, it is silent.","Yes, as an s.","Yes, as a z.","Only after 'au'."],a:0,ex:"Final s is normally silent in French: dos is said [do].",say:"J'ai mal au dos."}, {q:"Listen. Which comparison word did you hear?",opts:["mieux","moins","milieu","meilleur"],a:3,ex:"Meilleur ends with a clear 'eur' sound; mieux ends with 'eu' and no r.",say:"meilleur"}]},
    {t:"Comparing and saying what hurts",s:"Grammar",qs:[{q:"Complete: 'Paul est ___ grand ___ Marc.' (taller than)",opts:["moins / que","aussi / que","plus / que","plus / de"],a:2,ex:"'Plus + adjective + que' means 'more … than'."}, {q:"Complete: 'J'ai mal ___ tête.'",opts:["au","à la","aux","à le"],a:1,ex:"Tête is feminine, so avoir mal à + la tête stays 'à la'."}, {q:"Complete: 'Ce gâteau est ___ que l'autre.' (better)",opts:["meilleur","mieux","plus bon","bon"],a:0,ex:"Bon is irregular: its comparative is meilleur, never 'plus bon'."}]},
    {t:"Meilleur, mieux, superlatives",s:"Grammar",qs:[{q:"Complete: 'Elle chante ___ que sa sœur.' (better)",opts:["meilleure","plus bien","meilleur","mieux"],a:3,ex:"'Chante' needs an adverb, and the comparative of bien is mieux."}, {q:"Complete: 'C'est la ville la plus belle ___ France.'",opts:["en","dans","de","que"],a:2,ex:"The superlative uses 'de' to name the group: la plus belle de France."}, {q:"Complete: 'J'ai mal ___ dents.'",opts:["au","aux","à les","à la"],a:1,ex:"Dents is plural, and à + les always contracts to aux."}]},
    {t:"Reading: cities and doctors",s:"Reading",qs:[{q:"Read: 'Lyon est plus petite que Paris, mais elle est aussi belle. Pour moi, c'est la meilleure ville pour manger.' What does the writer think?",opts:["Lyon is the best city for food.","Lyon is bigger than Paris.","Paris is prettier than Lyon.","Lyon is the worst city for food."],a:0,ex:"'La meilleure ville pour manger' means the best city to eat in."}, {q:"Read: 'J'ai mal au ventre depuis trois jours et j'ai de la fièvre.' What is true about the patient?",opts:["headache for three days","stomach ache only three days ago","no temperature at all","stomach ache for three days"],a:3,ex:"'Depuis trois jours' with the present means it started three days ago and still continues."}, {q:"Read the prescription: 'Prendre un comprimé trois fois par jour, après les repas.' When do you take the tablet?",opts:["before meals, three times a day","once a day, after meals","after meals, three times a day","three tablets in the morning"],a:2,ex:"'Trois fois par jour' is three times a day and 'après les repas' is after meals."}]},
    {t:"Listening: at the doctor's",s:"Listening",qs:[{q:"Listen. What is the problem?",opts:["a headache and a fever","a sore throat and a cough","a backache and a cough","a sore throat and a fever"],a:1,ex:"'Mal à la gorge' is a sore throat and 'je tousse' means I'm coughing.",say:"J'ai mal à la gorge et je tousse."}, {q:"Listen. Who is taller?",opts:["her brother","Marie","they are the same","her sister"],a:0,ex:"'Moins grande que' means less tall than, so the brother is taller.",say:"Marie est moins grande que son frère."}, {q:"Listen. What does the doctor advise?",opts:["go for a walk and eat well","take tablets and sleep","drink coffee and rest","rest and drink lots of water"],a:3,ex:"'Reposez-vous' means rest and 'buvez beaucoup d'eau' means drink lots of water.",say:"Reposez-vous et buvez beaucoup d'eau."}]},
    {t:"At the doctor's and pharmacy",s:"Speaking",qs:[{q:"The doctor asks 'Qu'est-ce qui ne va pas ?' Best reply?",opts:["Je vais bien, merci, et vous ?","Ça va mieux que demain.","J'ai mal à la tête depuis hier.","Je suis la tête depuis hier."],a:2,ex:"The doctor asks what is wrong, so you describe a symptom with avoir mal à."}, {q:"A friend asks 'Ça va mieux ?' You feel better. Say:",opts:["Oui, je me sens beaucoup meilleur.","Oui, je me sens beaucoup mieux.","Oui, je suis beaucoup plus bon.","Oui, je me sens beaucoup bien."],a:1,ex:"'Se sentir' is followed by an adverb, so 'better' is mieux."}, {q:"At the pharmacy you have a doctor's prescription. Say:",opts:["Bonjour, j'ai une ordonnance du médecin.","Bonjour, j'ai une ordonnance de la boulangerie.","Bonjour, je suis une ordonnance du médecin.","Bonjour, j'ai mal à l'ordonnance."],a:0,ex:"You hand in une ordonnance from the doctor to get your medicine."}]},
    {t:"Writing comparisons",s:"Writing",qs:[{q:"Choose the correctly written comparison about your sister.",opts:["Ma sœur est aussi grande comme moi.","Ma sœur est aussi grand que moi.","Ma sœur est aussi grande que je.","Ma sœur est aussi grande que moi."],a:3,ex:"'Aussi … que' needs que, the adjective agrees with sœur, and after que you use moi."}, {q:"Fill the gap: 'C'est le ___ restaurant du quartier.'",opts:["mieux","plus bon","meilleur","bien"],a:2,ex:"Restaurant is a noun, so you need the adjective meilleur in the superlative."}, {q:"Which is the correct word order for 'the most expensive car'?",opts:["la plus voiture chère","la voiture la plus chère","la voiture plus la chère","la chère plus voiture"],a:1,ex:"When the adjective follows the noun, the article is repeated: la voiture la plus chère."}]},
    {t:"Health in France",s:"Culture",qs:[{q:"Which number do you call in France for a medical emergency (SAMU)?",opts:["15","18","17","911"],a:0,ex:"15 is the SAMU (medical), 18 the fire brigade, 17 the police; 112 also works across Europe."}, {q:"What is 'la carte Vitale'?",opts:["a train discount card","a gym membership card","a student ID card","the French health insurance card"],a:3,ex:"Patients show la carte Vitale at the doctor's and pharmacy so costs are reimbursed."}, {q:"A French friend says 'J'ai un chat dans la gorge.' What do they mean?",opts:["I swallowed a cat hair.","My cat is ill.","My voice is hoarse.","I am very hungry."],a:2,ex:"This idiom is like English 'a frog in my throat': a hoarse voice."}]},
    {t:"Review: comparisons and health",s:"Review",qs:[{q:"What is 'mieux'?",opts:["the adjective 'better' (from bon)","the adverb 'better' (from bien)","the word for 'worse'","the word for 'more'"],a:1,ex:"Mieux is the comparative of the adverb bien; meilleur comes from the adjective bon."}, {q:"Complete: 'J'ai mal ___ pied.'",opts:["au","à la","aux","à le"],a:0,ex:"Pied is masculine singular, so à + le contracts to au."}, {q:"Complete: 'Le train est ___ rapide ___ la voiture.' (as … as)",opts:["aussi / comme","autant / que","si / comme","aussi / que"],a:3,ex:"Equality with an adjective is aussi + adjective + que."}]},
    {t:"Challenge: superlatives",s:"Challenge",qs:[{q:"Which sentence about the film is correct?",opts:["C'est le plus bon film de l'année.","C'est le mieux film de l'année.","C'est le meilleur film de l'année.","C'est le meilleur film dans l'année."],a:2,ex:"Bon becomes le meilleur in the superlative, and the group is introduced by de."}, {q:"Complete: 'Parmi mes amis, c'est Léa qui parle ___ anglais.'",opts:["le meilleur","le mieux","la meilleure","plus bien"],a:1,ex:"Parler is a verb, so the superlative adverb le mieux is needed, even for a woman."}, {q:"Complete: 'C'est l'hôtel ___ cher de la ville.' (the least)",opts:["le moins","la moins","le plus moins","moins que"],a:0,ex:"Hôtel is masculine, and the superlative of less is le moins + adjective."}]}
  ]
];
